import { ok, fail } from './result.js';
import { balanceDue } from './payments.js';
import { isValidDate, daysBetween } from './dates.js';
import { roundCents } from './money.js';

/**
 * Get a list of overdue invoices.
 * @param {Array} invoices
 * @param {string} asOf date in YYYY-MM-DD format
 * @returns {{ ok: true, value: Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }> } | { ok: false, error: string }}
 */
export function overdueInvoices(invoices, asOf) {
  // Validate asOf date
  if (!isValidDate(asOf)) {
    return fail('DATE_INVALID');
  }

  const overdue = [];

  for (const invoice of invoices || []) {
    if (!invoice) continue;

    // Skip if not issued or partially_paid
    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid') {
      continue;
    }

    // Skip if dueDate is not before asOf
    if (daysBetween(invoice.dueDate, asOf) <= 0) {
      continue;
    }

    // Calculate days overdue
    const daysOverdue = daysBetween(invoice.dueDate, asOf);

    // Calculate due amount
    const due = balanceDue(invoice);

    overdue.push({
      number: invoice.number,
      customerId: invoice.customerId,
      dueDate: invoice.dueDate,
      daysOverdue,
      due,
    });
  }

  // Sort by daysOverdue descending (most overdue first)
  overdue.sort((a, b) => b.daysOverdue - a.daysOverdue);

  return ok(overdue);
}

/**
 * Get a VAT summary across all invoices.
 * @param {Array} invoices
 * @returns {{ ok: true, value: Array<{ rate: number, base: number, vat: number }> } | { ok: false, error: string }}
 */
export function vatSummary(invoices) {
  const vatByRate = {};

  for (const invoice of invoices || []) {
    if (!invoice) continue;

    // Skip if not issued, partially_paid, or paid
    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid') {
      continue;
    }

    // Process each line
    for (const line of invoice.lines || []) {
      // Calculate line total (gross amount)
      const gross = Math.round(line.qty * line.unitPrice);

      // Calculate discount
      const discount = line.discountPercent ? roundCents((gross * line.discountPercent) / 100) : 0;

      // Calculate base (amount VAT is calculated on)
      const base = gross - discount;

      // Calculate VAT for this line
      const lineVat = roundCents((base * line.vatRate) / 100);

      // Track by rate
      const rate = line.vatRate;
      if (!vatByRate[rate]) {
        vatByRate[rate] = { rate, base: 0, vat: 0 };
      }

      vatByRate[rate].base += base;
      vatByRate[rate].vat += lineVat;
    }
  }

  // Convert to array and sort by rate descending
  const summary = Object.values(vatByRate).sort((a, b) => b.rate - a.rate);

  return ok(summary);
}

/**
 * Calculate late fee for an invoice.
 * @param {{ status: string, dueDate: string, lines: Array }} invoice
 * @param {string} asOf date in YYYY-MM-DD format
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lateFee(invoice, asOf) {
  // Validate asOf date
  if (!isValidDate(asOf)) {
    return fail('DATE_INVALID');
  }

  // Invoice must have issued status or later
  if (!invoice || (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid')) {
    return ok(0);
  }

  // Calculate days overdue
  const daysOverdue = daysBetween(invoice.dueDate, asOf);

  // If not overdue, return 0
  if (daysOverdue <= 0) {
    return ok(0);
  }

  // Calculate amount due
  const due = balanceDue(invoice);

  // Calculate fee: 0.04% per day
  // 0.04% = 0.0004
  const fee = roundCents(due * daysOverdue * 0.0004);

  return ok(fee);
}

