  // 10 days overdue: gross = 10000000, bulk discount = 250000, net = 9750000, VAT = 2047500
  // total = 10000000 - 250000 + 2047500 = 11797500
  // fee = 11797500 * 10 * 0.0004 = 47190 cents

  const result = lateFee(largeInvoice, '2026-11-14');

  assert.equal(result.ok, true);
  assert.equal(result.value, 47190);
});

test('lateFee with long overdue period', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // dueDate is 2026-10-19, total is 11495
  // 70 days overdue (2026-10-19 to 2026-12-28): 11495 * 70 * 0.0004 = 322.26 → 322 cents

  const result = lateFee(issued, '2026-12-28');

  assert.equal(result.ok, true);
  assert.equal(result.value, 322);
});

