  const paid2 = recordPayment(paid1, { amount: 15000, date: '2026-10-25' }).value;
  // Remaining: 32475
  // 5 days overdue (dueDate 2026-10-19): 32475 * 5 * 0.0004 = 64.95 → 65 cents

  const result = lateFee(paid2, '2026-10-24');

  assert.equal(result.ok, true);
  assert.equal(result.value, 65);
});

