    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-06',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, []).value;

  // inv1: 2 * 9500 = 19000, bulk discount = 475, VAT = 3879, total = 22404
  // inv2: 1 * 9500 = 9500, no bulk, VAT = 1995, total = 11495
  // outstanding = 22404 + 11495 = 33899

  const result = dashboard([issued1, issued2], '2026-10-15');

