  // Create invoices for different customers with different amounts due
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 95000, bulk discount, VAT, etc.
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }], // 47500
  }).value;

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }], // 28500
  }).value;

  const inv4 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-06',
    lines: [{ sku: 'STICKER', qty: 50 }], // 2500
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, []).value;
  const issued3 = issueInvoice(inv3, []).value;
  const issued4 = issueInvoice(inv4, []).value;

  const result = dashboard([issued1, issued2, issued3, issued4], '2026-10-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.topCustomers.length, 3);
  // C-001 should be first (has two invoices: large one + sticker)
  assert.equal(result.value.topCustomers[0].customerId, 'C-001');
  assert(result.value.topCustomers[0].due > result.value.topCustomers[1].due);
  assert(result.value.topCustomers[1].due > result.value.topCustomers[2].due);
});

